ALTER TABLE messages
    ADD CONSTRAINT fk_messages_on_sender FOREIGN KEY (sender_id) REFERENCES users (user_id);

ALTER TABLE message_read_by
    ADD CONSTRAINT fk_message_read_by_on_message FOREIGN KEY (message_id) REFERENCES messages (message_id);

ALTER TABLE message_read_by
    ADD CONSTRAINT fk_message_read_by_on_user FOREIGN KEY (user_id) REFERENCES users (user_id);

-- safety & verification
ALTER TABLE afternoon_otps
    ADD CONSTRAINT fk_afternoon_otps_on_group FOREIGN KEY (group_id) REFERENCES child_groups (group_id);

ALTER TABLE afternoon_otps
    ADD CONSTRAINT fk_afternoon_otps_on_child FOREIGN KEY (child_id) REFERENCES children (child_id);

ALTER TABLE verification_logs
    ADD CONSTRAINT fk_verification_logs_on_ride FOREIGN KEY (ride_id) REFERENCES rides (ride_id);

ALTER TABLE verification_logs
    ADD CONSTRAINT fk_verification_logs_on_group FOREIGN KEY (group_id) REFERENCES child_groups (group_id);

ALTER TABLE verification_logs
    ADD CONSTRAINT fk_verification_logs_on_child FOREIGN KEY (child_id) REFERENCES children (child_id);

ALTER TABLE verification_logs
    ADD CONSTRAINT fk_verification_logs_on_driver FOREIGN KEY (driver_id) REFERENCES drivers (user_id);

-- =============================================================================
-- PERFORMANCE INDEXES
-- =============================================================================

-- User lookups
CREATE INDEX idx_users_email            ON users (email);
CREATE INDEX idx_users_provider         ON users (provider_type, provider_user_id);
CREATE INDEX idx_users_is_deleted       ON users (is_deleted);

-- Children
CREATE INDEX idx_children_parent        ON children (parent_id);
CREATE INDEX idx_children_group         ON children (group_id);

-- Rides
CREATE INDEX idx_rides_driver           ON rides (driver_id);
CREATE INDEX idx_rides_status           ON rides (status);
CREATE INDEX idx_rides_offer            ON rides (offer_id);

-- Ride passengers (most-queried in safety service)
CREATE INDEX idx_ride_passengers_ride_date ON ride_passengers (ride_id, date);

-- Schedules
CREATE INDEX idx_schedules_child_date   ON schedules (child_id, date);

-- Messages (time-ordered per room)
CREATE INDEX idx_messages_room_sent     ON messages (room_id, sent_at DESC);

-- Verification logs (analytics queries)
CREATE INDEX idx_verification_logs_type_at  ON verification_logs (verification_type, verified_at);
CREATE INDEX idx_verification_logs_ride     ON verification_logs (ride_id);

-- Afternoon OTPs (looked up by group + child + date)
CREATE INDEX idx_afternoon_otps_lookup  ON afternoon_otps (group_id, child_id, active_date);

-- Offers
CREATE INDEX idx_offers_status          ON offers (status);

-- Bookings
CREATE INDEX idx_bookings_parent        ON bookings (parent_id);
CREATE INDEX idx_bookings_offer         ON bookings (offer_id);
CREATE INDEX idx_bookings_dates         ON bookings (start_date, end_date);